INSERT INTO `pos_categories` VALUES (2,'bread','중분류',0,1),(3,'bread','일반빵',1,1),(4,'bread','크림빵',2,1),(5,'bread','조리빵',3,1),(6,'bread','파이/패스트리',4,1),(7,'bread','도넛/고로케',5,1),(8,'bread','바게뜨/건강빵',6,1),(9,'bread','식빵',7,1),(10,'bread','양과',8,1),(11,'bread','냉동볶음밥',9,1),(12,'sandwich','샌드위치',0,1),(13,'sandwich','샐러드',1,1);
