INSERT INTO `pos_products` VALUES (1,5635,'딥 초코 롱바게트','다크 초콜릿을 더한 바게트에 진한 가나슈와\n상큼한 라즈베리 잼을 샌드하고, 초콜릿을\n듬뿍 딥핑해 풍부한 초코 풍미를 살린 제품','',NULL,'a00d43b546bb496cae202811f97dc156.webp','2026-10-30 11:40:44'),(2,5636,'스위트 바통쉬크레(5개입)','바삭하고 버터 풍미 진한 패스트리에\n초콜릿을 듬뿍 코팅하여 더욱 달콤하고\n사랑스러워진 바통 쉬크레','',NULL,'790299ac5f1f4f71a2db8109a57b1745.webp','2026-10-30 11:40:45'),(3,5622,'사르르 호박 카스테라 크림빵(3개입)','달콤한 호박크림과 호박고지가 어우러진\n부드러운 빵에 카스테라 가루를 듬뿍 묻혀\n입안에서 사르르 녹는 간식빵','',4200,'f2b8ed1c4eec4c7ab2dc44bde9d88b56.webp','2026-10-30 11:40:45'),(4,5623,'꿀맛 고구마 생도넛','고구마 앙금을 가득 채우고\n조청시럽을 더해 달콤함을 담아낸\n부드럽고 촉촉한 고구마 생도넛','',1900,'f3140296b1f841b5bc726d77c6f30e41.webp','2026-10-30 11:40:46'),(5,5624,'흑임자 가나슈 바게트','바삭한 흑임자 바게트에 진한 흑임자 가나슈를\n듬뿍 채워 고소한 풍미와 달콤함이 어우러지는\n흑임자 바게트','',4900,'f711a0f8c878449d88a68eb91266cc9d.webp','2026-10-30 11:40:46'),(6,5625,'오리지널 퀴니아망','달콤한 설탕을 카라멜라이즈드하여\n바삭하게 구워낸 패스트리에 버터의 풍미를\n더해 달콤바삭한 매력을 살린 패스트리','',2800,'b86be796f7c043d89a3e1eb1a86a0d76.webp','2026-10-30 11:40:47'),(7,5626,'흑임자 퀴니아망','고소한 흑임자를 듬뿍 더한 패스트리에\n달콤한 풍미를 더해 바삭하게 구워낸\n달콤고소 흑임자 패스트리','',3000,'7d0763c9020a40e3959e4b101842e9cd.webp','2026-10-30 11:40:47'),(8,5627,'골든 버터 식빵','정통 브리오슈의 부드러운 식감을 그대로 담아\n촉촉하게 구워내고, 버터의 깊고 진한 풍미를\n듬뿍 더한 골든 버터 식빵','',4800,'c64c70b1bd7c4d1c9a22dc6ad2ee1ce5.webp','2026-10-30 11:40:47'),(9,5571,'오지치즈 포테이토 포카치아','부드럽고 쫄깃한 포카치아에 짭조름한 베이컨과\n웨지감자, 진한 오지치즈 소스를 더한\n풍미 가득 간식빵','',3600,'e093a1fb63db4979908a12941635d3a5.webp','2026-10-30 11:40:48'),(10,5572,'감바스 포카치아','부드럽고 쫄깃한 포카치아에 은은한 마늘 풍미,\n탱글한 새우가 들어간 감바스를 접목한\n감칠맛 가득 간식빵','',4100,'51f5d8873e95453a84e3c86f904610b2.webp','2026-10-30 11:40:48'),(11,5471,'고단백 현미식빵','탕종법을 사용해\n촉촉하고 쫄깃한 식감을 살리고,\n현미와 호두, 아몬드, 호박씨, 해바라기씨 등 \n다양한 견과류를 더해 고소하게 즐기기 좋은\n고단백 식빵','',3700,'a9583c6756e4460a836999427f807d0b.webp','2026-10-30 11:40:49'),(12,5467,'데일리 우유식빵','더 부드럽고 더 촉촉해진\n신선한 우유맛 가득한 식빵','',3800,'a879a7313feb43cfb7b60fc466cb1bee.webp','2026-10-30 11:40:49'),(13,5470,'고식이섬유&저당 곡물식빵','식이섬유가 풍부한 고대곡물 호라산밀과\n밀기울로 만들어 더 건강하고, 더 고소하게!\n샌드위치로도 활용하기 좋은 데일리 건강 식빵','',4900,'66074979ee4b4f4fbdc715fd35f785f3.webp','2026-10-30 11:40:49'),(14,5469,'그대로 구워먹는 꿀 토스트 식빵','꿀분말과 펄슈가를 넣어 은은한 단맛과 고소한\n버터 풍미로 토스트 하였을 때 가장 맛있는 식빵','',5000,'cf29fa232bf84b08a281057913c9ff05.webp','2026-10-30 11:40:50'),(15,5098,'2배 더 진한 우유 식빵','2배 더 진해진 우유 함량과\n순우유 탕종으로 보들보들한 빵결 속에\n진한 우유의 고소한 풍미를 가득 담은 우유 식빵','',5000,'993e6334e4bd4695a88fd08a4229b4de.webp','2026-10-30 11:40:50'),(16,5099,'2배 더 진한 우유 식빵(Half)','2배 더 진해진 우유 함량과\n순우유 탕종으로 보들보들한 빵결 속에\n진한 우유의 고소한 풍미를 가득 담은 우유 식빵','',NULL,'1f1d727548264650bda12af626c74a18.webp','2026-10-30 11:40:51'),(17,4436,'촉촉 쫄깃 탕종식빵','탕종을 넣어 더욱 촉촉하고 쫄깃한 식감과\n은은한 단맛이 어우러지는 담백 식빵','',5400,'6967108190774890a9870deaf9a1acb6.webp','2026-10-30 11:40:51'),(18,3949,'生生 생크림 식빵','마스카포네 생크림을 넣어 극강의 부드러움과\n마지막까지 은은한 단맛을 느낄 수 있는\n뚜레쥬르 대표 식빵','',5500,'d932675ec0e5422aa46f868801e34cce.webp','2026-10-30 11:40:51'),(19,2507,'TLJ 옥수수식빵','한층 더 촉촉해지고 옥수수 맛이 풍부한 빵 속에\n고소한 옥수수 알갱이가 톡톡 씹히는 식빵','',5000,'6ce4dcc26e7948fa83407a3810d3d453.webp','2026-10-30 11:40:52'),(20,5124,'기본좋은 소금버터식빵','3개의 이즈니버터 홀로 깊어진 풍미와\n소금의 짭조름한 맛을 더 바삭하고 더 쫄깃하게\n즐길 수 있는 시그니처 식빵\n\n*본 제품에 들어간 가루쌀은 물에 불리지 않고\n빻을 수 있는 국산 쌀 품종으로\n농가와 상생하는 착한 원료입니다.','',4000,'b0a81c8ade6641499e05bb950f63b5db.webp','2026-10-30 11:40:52'),(21,5607,'고식이섬유 통밀식빵','통밀, 밀기울, 리너지 가루를 블랜딩해\n식이섬유는 풍부하게, 토스트부터 샌드위치까지 다양하게 즐기는 고식이섬유 통밀식빵','',NULL,'541c428a6adc49058440e09031110190.webp','2026-10-30 11:40:53'),(22,2523,'호박 패스트리 식빵','호박의 고소한 맛을 살린 바삭한 패스트리 식빵','',NULL,'342406b33da04b3ba69de80f6cceadb7.webp','2026-10-30 11:40:53'),(23,4635,'마구마구 밤식빵(대)','부드럽고 촉촉한 반죽에 밤다이스와 밤크림이\n듬뿍 들어가 밤 맛의 풍부함을 \n한 층 업그레이드한 제품','',NULL,'867bbd54ff534480b4794aa068abc4fb.webp','2026-10-30 11:40:54'),(24,4636,'마구마구 밤식빵(소)','부드럽고 촉촉한 반죽에 밤다이스와 밤크림이\n듬뿍 들어가 밤 맛의 풍부함을 한 층\n업그레이드한 제품','',4000,'47b9271382c14fbda4292abb2365cba4.webp','2026-10-30 11:40:54'),(25,5573,'더블 초코 바게트','다크•밀크 초콜릿을 듬뿍 더해 달콤함도 더블!\n진한 카카오 풍미와 호두의 고소함을 담은\n부드러운 초코 바게트','',NULL,'dbd484eb6d0a4b98b9b3fe7458efcf19.webp','2026-10-30 11:40:55'),(26,5556,'소시지&불고기 라우겐','담백하고 쫄깃한 라우겐에 소시지와 \n달콤짭조름한 소불고기를 듬뿍 담아 \n든든하게 즐기는 조리빵','',NULL,'d769e6f3bea24839bafad72467c9f313.webp','2026-10-30 11:40:55'),(27,5237,'바삭 마늘빵(5개입)','마늘의 향긋함과 버터의 고소한 맛을\n그대로 담은 바삭한 식감의 마늘 바게트','',3600,'1e347ad6d71e4eef82a47cf76f30c91d.webp','2026-10-30 11:40:55'),(28,5123,'기본좋은 쌀 베이글','국내산 쌀로 만든 쌀 탕종과 발효당으로\n더 쫄깃하고 촉촉하게 구워낸 쌀 베이글\n\n*본 제품에 들어간 가루쌀은 물에 불리지 않고\n빻을 수 있는 국산 쌀 품종으로\n농가와 상생하는 착한 원료입니다.','',2900,'e02e2294f8f746168c6da0cdacebcdc0.webp','2026-10-30 11:40:56'),(29,5122,'기본좋은 올리브 베이글','국내산 쌀 탕종과 발효당을 더한 반죽에\n올리브를 더해 감칠맛은 더 올리고\n쫄깃한 식감을 살려 구워낸 쌀 베이글\n\n*본 제품에 들어간 가루쌀은 물에 불리지 않고\n빻을 수 있는 국산 쌀 품종으로\n농가와 상생하는 착한 원료입니다.','',3000,'039017a01fc747298dbcb7347a652dd5.webp','2026-10-30 11:40:56'),(30,4807,'데일리 베이글','폭신하고 쫄깃한 기지에 담백한 플레인 베이글','',NULL,'58e699b6c0854056abe7459de7a5f1c6.webp','2026-10-30 11:40:57'),(31,4808,'데일리 블루베리 베이글','폭신하고 쫄깃한 기지에 새콤달콤한 블루베리가 콕콕 박혀있는 블루베리 베이글','',NULL,'fc0279bff90d41c398651b17ef43f98a.webp','2026-10-30 11:40:57'),(32,5608,'고식이섬유 통밀빵','통밀, 밀기울, 리너지 가루를 블랜딩해\n식이섬유는 풍부하게, 촉촉하고 부드러운\n식감으로 더욱 건강하게 즐기는\n고식이섬유 통밀빵','',4300,'95676b49e592424c98e6b39f5d3ae9f9.webp','2026-10-30 11:40:58'),(33,5490,'올리브 치즈 롱파뉴','짭조름한 올리브와 치즈, 고소한 견과류와\n달콤한 크랜베리를 더해 \n그냥 먹어도 맛있는 롱~한 깜파뉴','',4100,'9270b1c96f64417db3acbea5f14b31f3.webp','2026-10-30 11:40:58'),(34,5489,'후르츠 호밀 사워도우','은은한 산미가 매력적인 발아 호밀이 들어간 \n사워도우에 대추야자, 건자두, 건포도를 더해 \n쫀득하고 달콤하게 즐기는 식사빵','',5500,'a517582b7ca446d5824fa5ad08880c30.webp','2026-10-30 11:40:58'),(35,5235,'호두 바게트','고소한 호두를 더해 풍미와\n씹는 식감이 더해진 호두 바게트','',NULL,'44f05dcd3dcf4d6f895d4fecf13a9003.webp','2026-10-30 11:40:59'),(36,5236,'호두 연유 바게트','고소한 풍미 가득 호두 바게트에\n연유크림을 더해 달콤하게 즐기는\n간식형 바게트','',4500,'329d91e0a0504c4fbcb1b9266404c5ee.webp','2026-10-30 11:40:59'),(37,5012,'고단백 하루견과 곡물브레드','고소한 빵에 견과류를 듬뿍 넣어 고소하고\n담백한 맛을 느낄 수 있는 고단백 건강빵','',6300,'3a68d83cd29e463184c5a5c9b772e0e0.webp','2026-10-30 11:41:00'),(38,5234,'프랑스 바게트','프랑스산 밀가루가 들어가\n겉은 더 바삭하고 속은 더 촉촉한,\n구수한 맛의 정통 바게트','',4500,'05f189e1715f4c68baa81d531471bb5e.webp','2026-10-30 11:41:00'),(